-- An invitation may name its invitee by handle: Better Auth still keys
-- it to the invitee's stored address, and Keel answers the handle in its place.
-- Generated by better-auth 1.7.7's compileMigrations from the organization
-- plugin's invitation.additionalFields, and held equal to them by [ba.schema].
-- Expand-only: a nullable column and an index.
alter table "invitation" add column "handle" text;

create index "invitation_handle_idx" on "invitation" ("handle");
